import{_ as e,c as o,o as s,ag as n}from"./chunks/framework.Cycwnjj0.js";const a="/assets/appearance-settings-under-settings-in-azonpress-dashboard.CGOBMhu4.webp",r="/assets/product-ui-style.22gvAru9.webp",i="/assets/link-defaults.CAx9C1SL.webp",l="/assets/button-appearance.-uS4Ob6d.webp",p="/assets/custom-button-styler.kVXRBM-I.webp",f=JSON.parse('{"title":"Appearance Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miscellaneous/appearance-settings.md","filePath":"guide/miscellaneous/appearance-settings.md"}'),u={name:"guide/miscellaneous/appearance-settings.md"};function c(g,t,h,d,b,y){return s(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="appearance-settings" tabindex="-1">Appearance Settings <a class="header-anchor" href="#appearance-settings" aria-label="Permalink to &quot;Appearance Settings&quot;">​</a></h1><p>In AzonPress, the &quot;<strong>Appearance Settings</strong>&quot; option allows you to customize the appearance of your Product Tables and Comparison Tables displayed on your site in multiple ways, ensuring that they look the way you want them to on your website. This article guides you through customizing the tables using <strong>Appearance Settings</strong> with <strong>AzonPress</strong>.</p><h2 id="global-style-settings" tabindex="-1">Global Style Settings <a class="header-anchor" href="#global-style-settings" aria-label="Permalink to &quot;Global Style Settings&quot;">​</a></h2><p>To learn the use of Appearance Settings, follow the steps with screenshots below –</p><p>First, go to <strong>Settings</strong> from the <strong>AzonPress Navbar</strong> and click on <strong>Appearance Settings.</strong> Now, you will get all the options for customizing the look of your tables.</p><p>Once you complete all the customization, click the <strong>Update Settings</strong> button to save all the changes.</p><p><img src="'+a+'" alt="Appearance Settings under Settings in AzonPress dashboard"></p><p>Here on the <strong>Global Style Settings</strong> page, you will get <strong>four major</strong> settings options to customize your table. These are:</p><ul><li>Product UI Style</li><li>Link defaults</li><li>Button Appearance</li><li>Custom Button Styler</li></ul><p><strong>All the Settings options are explained in the screenshots below –</strong></p><h3 id="product-ui-style" tabindex="-1">Product UI Style <a class="header-anchor" href="#product-ui-style" aria-label="Permalink to &quot;Product UI Style&quot;">​</a></h3><p>Under this setting, you will get the option to change the UI style for your Products in two different styles either <strong>Modern Style</strong> (i.e., more bold design) or <strong>Classic Style</strong> (i.e., normal design).</p><p><img src="'+r+'" alt="Product UI Style"></p><h3 id="link-defaults" tabindex="-1">Link defaults <a class="header-anchor" href="#link-defaults" aria-label="Permalink to &quot;Link defaults&quot;">​</a></h3><p>Under these settings, you will find different options to customize your external link redirection.</p><p>All the available options under this Setting are briefly explained in the screenshot below –</p><p><strong>New Window</strong>: Enable this option if you want to open AzonPress links always in a new window or tab whenever someone clicks on it.</p><p><strong>No Follow</strong>: To prevent spam on interactive pages regarding external links, enable this option. No follow markup will help visitors not to create spam to add a link to their website to the content they create.</p><p><strong>No Index</strong>: If you want the No Index, No Follow attribute applied to the AzonPress page meta by default, enable this checkbox.</p><p><strong>Hide Price</strong>: If you want to hide the price field, enable this checkbox.</p><p><strong>Hide Prime Status</strong>: If you want to hide the prime status, enable this checkbox.</p><p><strong>Hide Label in Mobile Device</strong>: If you want to hide the comparison table label on the mobile device, enable this option.</p><p><strong>Show Disclaimer Text</strong>: Enable this checkbox if you want to show any disclaimer text. Plus, if you use this <strong>%last_update%</strong> text in your <strong>Disclaimer Text</strong> field, it will show the date of your tables&#39; last update with the disclaimer.</p><p><img src="'+i+'" alt="Link Defaults"></p><h3 id="button-appearance" tabindex="-1">Button Appearance <a class="header-anchor" href="#button-appearance" aria-label="Permalink to &quot;Button Appearance&quot;">​</a></h3><p>In the Button Appearance setting, you will get two different button styles with multiple template designs for your tables. These are:</p><ul><li>Buy Now Button Style</li><li>Add To Cart Button Style</li></ul><p>Choose any button that you wish to appear on your table.</p><p><img src="'+l+'" alt="Button Appearance"></p><h3 id="custom-button-styler" tabindex="-1">Custom Button Styler <a class="header-anchor" href="#custom-button-styler" aria-label="Permalink to &quot;Custom Button Styler&quot;">​</a></h3><p>With this setting, you can <strong>customize</strong> your <strong>button&#39;s style</strong> by <strong>changing</strong> its <strong>color</strong>, <strong>background</strong>, <strong>border</strong>, etc as per your needs. Additionally, you can design your button, for both <strong>Normal</strong> and <strong>Hover</strong> state.</p><p>Once you are done with the customization, click the <strong>Update Settings</strong> button to save all the changes.</p><p><img src="'+p+'" alt="Custom Button Styler"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',35)])])}const w=e(u,[["render",c]]);export{f as __pageData,w as default};
